/* Satu rekening operasional. Saldo sengaja dibuat TIDAK cukup untuk membayar
   semua yang lolos kontrol, supaya cabang "kas tidak cukup" benar-benar hidup
   di setiap demo, bukan cuma ada di kode. */
const d = new Date();
return [{ json: {
  account_code: 'OPS-IDR-01', bank_name: 'Bank Mandiri', account_number: '1220004455667',
  currency: 'IDR', balance: 900000000, min_buffer: 150000000, cost_of_cash_pct: 12,
  as_of: d.toISOString().slice(0, 10)
} }];

/* Dua pembayaran terdahulu, supaya penjaga pembayaran ganda punya sesuatu yang
   nyata untuk ditangkap - dua-duanya:
     PAY-1007  sudah LUNAS di run lama                        -> DUPLICATE
     PAY-1014  sudah masuk berkas bank, balasannya belum ada  -> IN_FLIGHT
   Tanpa baris kedua, penjaga yang mencegah pembayaran ganda saat run dijalankan
   dua kali sebelum bank membalas tidak pernah terbukti. */
function hari(n) { const d = new Date(); d.setDate(d.getDate() + n); return d.toISOString().slice(0, 10); }
return [
  { json: {
    line_key: 'RUN-SEED|SINAR BAJA ELEKTRIK|PAY-1007',
    run_key: 'RUN-SEED', vendor: 'Sinar Baja Elektrik', invoice_number: 'PAY-1007',
    amount: 22000000, currency: 'IDR', status: 'settled', route_to: 'accounting_auto',
    hold_code: '', hold_reason: '', account_number_masked: '******7766',
    pay_on: hari(-21), discount_taken: 0, bank_ref: 'TRX-SEED-0001',
    settled_on: hari(-20), reject_reason: '', execution_id: 'seed'
  } },
  { json: {
    line_key: 'RUN-SEED-2|BERKAH JAYA MANDIRI|PAY-1014',
    run_key: 'RUN-SEED-2', vendor: 'Berkah Jaya Mandiri', invoice_number: 'PAY-1014',
    amount: 9800000, currency: 'IDR', status: 'to_pay', route_to: 'accounting_auto',
    hold_code: '', hold_reason: '', account_number_masked: '******7889',
    pay_on: hari(-1), discount_taken: 0, bank_ref: '',
    settled_on: '', reject_reason: '', execution_id: 'seed'
  } }
];
